import{_ as o,c as t,o as s,ae as n}from"./chunks/framework.CliRSA9F.js";const u=JSON.parse('{"title":"Analytics Connections","description":"","frontmatter":{},"headers":[],"relativePath":"features/analytics-connections.md","filePath":"features/analytics-connections.md"}'),r={name:"features/analytics-connections.md"};function a(i,e,l,h,c,d){return s(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="analytics-connections" tabindex="-1">Analytics Connections <a class="header-anchor" href="#analytics-connections" aria-label="Permalink to &quot;Analytics Connections&quot;">​</a></h1><h2 id="all-your-numbers-in-one-place-next-to-your-rankings" tabindex="-1">All Your Numbers in One Place, Next to Your Rankings <a class="header-anchor" href="#all-your-numbers-in-one-place-next-to-your-rankings" aria-label="Permalink to &quot;All Your Numbers in One Place, Next to Your Rankings&quot;">​</a></h2><p>Your listening numbers are scattered: Spotify for Creators has one set, Apple Podcasts Connect another, YouTube Studio a third, and your podcast host yet another. Analytics connections bring them into PodSEO, so you can see plays, listeners, followers and downloads on the same screen as your keyword rankings and visibility, and judge whether your SEO work is turning into an audience.</p><p>Every connection is <strong>free on every plan</strong>, including the Free plan. You can connect as many sources as apply to your show; each one adds its own tab.</p><p><strong>To access</strong>: Click <strong>Analytics</strong> in the sidebar, just below <strong>Traction</strong>. The page has one tab per source: <strong>Spotify</strong>, <strong>YouTube</strong>, <strong>Apple Podcasts</strong>, <strong>Hosting</strong>, <strong>Tracker</strong> (OP3), and <strong>hopr.fm</strong>. YouTube opens its own page, <a href="/features/youtube-insights.html">YouTube Insights</a>. Each tab carries a step-by-step setup guide, so you can follow along in the app while you connect.</p><p><strong>Who can connect</strong>: In a personal account, you can connect and disconnect everything. In an organization, only <strong>Admins</strong> and <strong>Owners</strong> can connect or disconnect a source; other team members can view the numbers.</p><p><strong>Read-only access</strong>: PodSEO only reads statistics. It never publishes, edits or deletes anything on Spotify, Apple, YouTube or your host, and you never share a password with PodSEO.</p><hr><h2 id="spotify-for-creators" tabindex="-1"><strong>Spotify for Creators</strong> <a class="header-anchor" href="#spotify-for-creators" aria-label="Permalink to &quot;**Spotify for Creators**&quot;">​</a></h2><p>Spotify&#39;s own data on how listeners discover and play your show: where impressions come from, how many turn into plays, and who your listeners are.</p><h3 id="how-to-connect" tabindex="-1"><strong>How to connect</strong> <a class="header-anchor" href="#how-to-connect" aria-label="Permalink to &quot;**How to connect**&quot;">​</a></h3><p>Your show needs to be linked to Spotify in PodSEO first (you can check this on the <a href="/features/distribution-health.html">Distribution Health</a> page).</p><ol><li>Open <strong>Analytics</strong> and select the <strong>Spotify</strong> tab. PodSEO shows a one-time code for your show. The code is valid for 30 days.</li><li>In <strong>Spotify for Creators</strong>, go to <strong>Manage</strong> &gt; <strong>Team</strong> and invite <code>spotify@podseo.com</code>.</li><li>Paste the PodSEO code into the invite&#39;s <strong>Title</strong> field. This is how PodSEO knows the invite comes from you.</li><li>Set <strong>Analytics</strong> to <strong>Reader</strong> and leave everything else (Episodes, Interact, Monetize, Settings) on <strong>No access</strong>.</li><li>Send the invite. PodSEO checks for new invites every 10 minutes, so your Spotify tab fills in shortly after.</li></ol><p>If Spotify refuses the connection (for example because the team access isn&#39;t set as described above), the Spotify tab shows a card explaining what to fix. Correct the access in Spotify, or send a new invite, then connect again.</p><h3 id="what-you-ll-see" tabindex="-1"><strong>What you&#39;ll see</strong> <a class="header-anchor" href="#what-you-ll-see" aria-label="Permalink to &quot;**What you&#39;ll see**&quot;">​</a></h3><ul><li><strong>Daily plays</strong> over time</li><li><strong>Discovery</strong>: impressions from <strong>Search</strong>, <strong>Home</strong>, <strong>Library</strong> and <strong>Other</strong>, and the funnel from impression to play, so you can see how often being seen turns into being listened to</li><li><strong>Engagement</strong>: new followers, hours listened (compared with the previous 30 days), and new versus returning listeners</li><li><strong>Audience</strong>: age, gender, countries, regions, cities, devices and listening apps</li><li><strong>Episodes</strong>: each episode&#39;s impressions, impressions from Search, and plays</li></ul><p>Impressions from <strong>Search</strong> are the most direct link to your SEO work: they show how often your show appears when people search on Spotify.</p><h3 id="how-fresh" tabindex="-1"><strong>How fresh</strong> <a class="header-anchor" href="#how-fresh" aria-label="Permalink to &quot;**How fresh**&quot;">​</a></h3><p>Spotify data is updated daily. The first read covers the last 90 days. Discovery, engagement and audience figures use Spotify&#39;s own last-30-days windows.</p><h3 id="disconnecting" tabindex="-1"><strong>Disconnecting</strong> <a class="header-anchor" href="#disconnecting" aria-label="Permalink to &quot;**Disconnecting**&quot;">​</a></h3><p>Click <strong>Disconnect</strong> on the Spotify tab. PodSEO stops reading your Spotify analytics and your Spotify numbers no longer show anywhere in PodSEO; PodSEO keeps them for when you reconnect. To end PodSEO&#39;s access completely, also remove <code>spotify@podseo.com</code> from your show&#39;s team in Spotify for Creators.</p><hr><h2 id="apple-podcasts-connect" tabindex="-1"><strong>Apple Podcasts Connect</strong> <a class="header-anchor" href="#apple-podcasts-connect" aria-label="Permalink to &quot;**Apple Podcasts Connect**&quot;">​</a></h2><p>Apple&#39;s data on plays, listeners, followers and how much of each episode people actually hear.</p><h3 id="how-to-connect-1" tabindex="-1"><strong>How to connect</strong> <a class="header-anchor" href="#how-to-connect-1" aria-label="Permalink to &quot;**How to connect**&quot;">​</a></h3><p>Your show must be listed on Apple Podcasts.</p><ol><li>Open <strong>Analytics</strong> and select the <strong>Apple Podcasts</strong> tab.</li><li>In <strong>Apple Podcasts Connect</strong>, go to <strong>Account</strong> &gt; <strong>People</strong> and invite <code>applepodcasts@podseo.com</code>.</li><li>Give the invite the <strong>Analyst</strong> role and select your show.</li><li>Send the invitation. PodSEO checks for new invitations every 10 minutes.</li></ol><p><strong>Proving the show is yours.</strong> Before showing Apple data, PodSEO checks that the show belongs to you:</p><ul><li>If the <strong>owner email in your RSS feed</strong> matches a verified email on your PodSEO account (or on your organization&#39;s account), the check is automatic.</li><li>Otherwise, PodSEO sends a one-time link to the owner email in your RSS feed. The link is valid for 14 days. Whoever reads that mailbox clicks <strong>Yes, this is us</strong> to confirm, or <strong>No, I don&#39;t know PodSEO</strong> to refuse.</li></ul><p>Once one show is proven, other shows from the same Apple Podcasts Connect team are approved too.</p><h3 id="what-you-ll-see-1" tabindex="-1"><strong>What you&#39;ll see</strong> <a class="header-anchor" href="#what-you-ll-see-1" aria-label="Permalink to &quot;**What you&#39;ll see**&quot;">​</a></h3><ul><li><strong>Plays</strong>, <strong>Hours listened</strong> and <strong>Listeners</strong> for the last 60 days, with a daily plays chart</li><li><strong>Followers</strong>: total, gained, lost and net</li><li><strong>Time listened</strong> by followers compared with everyone else</li><li><strong>Monthly history</strong> of Plays, Listeners, Engaged listeners and Hours</li><li><strong>Episodes table</strong> with Plays, Listeners, Engaged, Avg. listened, First 7 days and First 30 days for each episode, plus a <strong>retention curve</strong> per episode showing where listeners drop off</li><li><strong>Audience</strong>: countries, top cities, engaged versus casual listeners, and followers versus other listeners</li></ul><p>Use the <strong>30</strong>, <strong>90</strong> and <strong>365 days</strong> tabs to change the period.</p><h3 id="how-fresh-1" tabindex="-1"><strong>How fresh</strong> <a class="header-anchor" href="#how-fresh-1" aria-label="Permalink to &quot;**How fresh**&quot;">​</a></h3><p>Apple data is read daily. PodSEO keeps a rolling 60 days of daily data plus monthly history going back as far as Apple keeps it.</p><h3 id="disconnecting-1" tabindex="-1"><strong>Disconnecting</strong> <a class="header-anchor" href="#disconnecting-1" aria-label="Permalink to &quot;**Disconnecting**&quot;">​</a></h3><p>Click <strong>Disconnect</strong> on the Apple Podcasts tab. PodSEO stops reading your Apple analytics and your Apple numbers no longer show anywhere in PodSEO; PodSEO keeps them for when you reconnect. To end PodSEO&#39;s access completely, also remove <code>applepodcasts@podseo.com</code> from <strong>Account</strong> &gt; <strong>People</strong> in Apple Podcasts Connect.</p><hr><h2 id="youtube" tabindex="-1"><strong>YouTube</strong> <a class="header-anchor" href="#youtube" aria-label="Permalink to &quot;**YouTube**&quot;">​</a></h2><p>How people find and watch your podcast on YouTube, including the real search terms that bring viewers in.</p><h3 id="how-to-connect-2" tabindex="-1"><strong>How to connect</strong> <a class="header-anchor" href="#how-to-connect-2" aria-label="Permalink to &quot;**How to connect**&quot;">​</a></h3><ol><li>Open <strong>Analytics</strong> and select the <strong>YouTube</strong> tab (or click it to open the YouTube Insights page).</li><li>Click <strong>Connect YouTube</strong> and sign in with the Google account (or Brand Account) that owns your podcast&#39;s channel.</li><li>Click <strong>Activate Insights</strong>. PodSEO imports the last 6 months of your channel&#39;s data.</li></ol><h3 id="what-you-ll-see-2" tabindex="-1"><strong>What you&#39;ll see</strong> <a class="header-anchor" href="#what-you-ll-see-2" aria-label="Permalink to &quot;**What you&#39;ll see**&quot;">​</a></h3><ul><li><strong>Views</strong>, <strong>Watch hours</strong>, <strong>Subscribers</strong> (net) and the <strong>% of views from YouTube search</strong>, with a daily views chart</li><li><strong>Traffic sources</strong> and external referrers</li><li><strong>Search terms</strong> YouTube reports, compared with the keywords you track in PodSEO</li><li><strong>Episode-to-video matching</strong>, with keyword-based title suggestions for your videos</li><li><strong>Audience</strong>: countries, age and gender, cities, US states, operating systems and playback locations</li><li>Your <strong>podcast playlists</strong></li></ul><p>Use the <strong>7</strong>, <strong>28</strong> and <strong>90 days</strong> tabs to change the period.</p><h3 id="how-fresh-2" tabindex="-1"><strong>How fresh</strong> <a class="header-anchor" href="#how-fresh-2" aria-label="Permalink to &quot;**How fresh**&quot;">​</a></h3><p>Core figures are updated daily; the breakdowns (such as audience and traffic details) weekly.</p><h3 id="free-plan-limit" tabindex="-1"><strong>Free plan limit</strong> <a class="header-anchor" href="#free-plan-limit" aria-label="Permalink to &quot;**Free plan limit**&quot;">​</a></h3><p>On the Free plan you see channel performance, one reported search term and your latest episode. Paid plans show everything.</p><h3 id="disconnecting-2" tabindex="-1"><strong>Disconnecting</strong> <a class="header-anchor" href="#disconnecting-2" aria-label="Permalink to &quot;**Disconnecting**&quot;">​</a></h3><p>Your YouTube data is deleted when the authorization is revoked. For the full walkthrough of YouTube, see <a href="/features/youtube-insights.html">YouTube Insights</a>.</p><hr><h2 id="hosting-spreaker-and-buzzsprout" tabindex="-1"><strong>Hosting (Spreaker and Buzzsprout)</strong> <a class="header-anchor" href="#hosting-spreaker-and-buzzsprout" aria-label="Permalink to &quot;**Hosting (Spreaker and Buzzsprout)**&quot;">​</a></h2><p>Downloads straight from your podcast host. Spreaker and Buzzsprout are supported today, and more hosts are coming.</p><h3 id="how-to-connect-3" tabindex="-1"><strong>How to connect</strong> <a class="header-anchor" href="#how-to-connect-3" aria-label="Permalink to &quot;**How to connect**&quot;">​</a></h3><p>The <strong>Hosting</strong> tab appears when your podcast&#39;s feed is hosted on Spreaker or Buzzsprout.</p><p><strong>Spreaker</strong></p><ol><li>Open <strong>Analytics</strong> and select the <strong>Hosting</strong> tab.</li><li>Click <strong>Sign in to Spreaker</strong>.</li><li>Approve the request with <strong>Authorize</strong>. You&#39;re sent back to PodSEO and the first sync begins.</li></ol><p><strong>Buzzsprout</strong></p><ol><li>In Buzzsprout, open your profile and its <strong>API</strong> section, then copy the API token of the account that hosts your podcast.</li><li>In PodSEO, open <strong>Analytics</strong> and select the <strong>Hosting</strong> tab.</li><li>Paste the token and click <strong>Connect Buzzsprout</strong>. PodSEO matches your podcast through its RSS feed and the first sync begins.</li></ol><p>A Buzzsprout token can also edit your Buzzsprout account. PodSEO stores it encrypted and only uses it to read reports, never to change anything.</p><h3 id="what-you-ll-see-3" tabindex="-1"><strong>What you&#39;ll see</strong> <a class="header-anchor" href="#what-you-ll-see-3" aria-label="Permalink to &quot;**What you&#39;ll see**&quot;">​</a></h3><ul><li><strong>Downloads</strong>, <strong>Daily average</strong> and <strong>Best day</strong> for the period, with a daily chart</li><li><strong>Episodes</strong> with Total downloads, First 7 days and First 30 days, so you can compare launches fairly</li><li><strong>Unique listeners per week</strong>, as Spreaker reports them (Spreaker only: Buzzsprout doesn&#39;t report unique listeners)</li><li><strong>Who listens</strong>: countries, apps, devices and operating systems, when your Spreaker plan includes them. With Buzzsprout: countries, devices and the apps listeners download each episode with, day by day</li></ul><h3 id="how-fresh-3" tabindex="-1"><strong>How fresh</strong> <a class="header-anchor" href="#how-fresh-3" aria-label="Permalink to &quot;**How fresh**&quot;">​</a></h3><p>Downloads are synced daily. Spreaker audience details refresh weekly and the first sync backfills the last 365 days. Buzzsprout audience details refresh daily and the first sync reads all the history Buzzsprout still has.</p><h3 id="disconnecting-3" tabindex="-1"><strong>Disconnecting</strong> <a class="header-anchor" href="#disconnecting-3" aria-label="Permalink to &quot;**Disconnecting**&quot;">​</a></h3><p>Click <strong>Disconnect</strong> on the Hosting tab. PodSEO stops reading your downloads and deletes the access it stored. Your host numbers no longer show anywhere in PodSEO; PodSEO keeps them for when you reconnect.</p><ul><li><strong>Spreaker</strong>: PodSEO also asks Spreaker to revoke its access. You can check the connected apps in your Spreaker settings.</li><li><strong>Buzzsprout</strong>: Buzzsprout has no way for PodSEO to revoke a token. To invalidate it, delete or regenerate it in your Buzzsprout profile.</li></ul><hr><h2 id="op3-tracker-tab" tabindex="-1"><strong>OP3 (Tracker tab)</strong> <a class="header-anchor" href="#op3-tracker-tab" aria-label="Permalink to &quot;**OP3 (Tracker tab)**&quot;">​</a></h2><p><a href="https://op3.dev" target="_blank" rel="noreferrer">OP3</a> is a free, open podcast download tracker that many podcasters add to their feed as a prefix.</p><h3 id="how-to-connect-4" tabindex="-1"><strong>How to connect</strong> <a class="header-anchor" href="#how-to-connect-4" aria-label="Permalink to &quot;**How to connect**&quot;">​</a></h3><p>There&#39;s nothing to connect. If your RSS feed already carries the OP3 prefix, PodSEO finds it on its own (it checks your feed weekly) and the <strong>Tracker</strong> tab shows your numbers.</p><h3 id="what-you-ll-see-4" tabindex="-1"><strong>What you&#39;ll see</strong> <a class="header-anchor" href="#what-you-ll-see-4" aria-label="Permalink to &quot;**What you&#39;ll see**&quot;">​</a></h3><ul><li><strong>Downloads per episode</strong> at 1, 7 and 30 days after release</li><li>Your <strong>Latest</strong>, <strong>Typical</strong> and <strong>Best</strong> episode, so you can tell at a glance whether a new episode is doing better or worse than usual</li><li><strong>Listening apps</strong> (web browsers are excluded)</li></ul><h3 id="how-fresh-4" tabindex="-1"><strong>How fresh</strong> <a class="header-anchor" href="#how-fresh-4" aria-label="Permalink to &quot;**How fresh**&quot;">​</a></h3><p>OP3 data is public, so anyone can look at it, and it covers about 60 days of history.</p><h3 id="disconnecting-4" tabindex="-1"><strong>Disconnecting</strong> <a class="header-anchor" href="#disconnecting-4" aria-label="Permalink to &quot;**Disconnecting**&quot;">​</a></h3><p>Because PodSEO reads public OP3 data, there&#39;s no connection to remove. To stop OP3 tracking altogether, remove the OP3 prefix in your host&#39;s settings.</p><hr><h2 id="hopr-fm-podseo-s-download-prefix" tabindex="-1"><strong>hopr.fm (PodSEO&#39;s Download Prefix)</strong> <a class="header-anchor" href="#hopr-fm-podseo-s-download-prefix" aria-label="Permalink to &quot;**hopr.fm (PodSEO&#39;s Download Prefix)**&quot;">​</a></h2><p>hopr.fm is PodSEO&#39;s own download prefix. Like other analytics prefixes, it sits in front of your audio files and counts each download on its way to the listener. It&#39;s useful when your host doesn&#39;t give you good download numbers, or when you want a second, independent count.</p><h3 id="how-to-connect-5" tabindex="-1"><strong>How to connect</strong> <a class="header-anchor" href="#how-to-connect-5" aria-label="Permalink to &quot;**How to connect**&quot;">​</a></h3><ol><li>Open <strong>Analytics</strong> and select the <strong>hopr.fm</strong> tab.</li><li>Click <strong>Get my prefix</strong>. PodSEO creates your personal prefix in the form <code>https://hopr.fm/k/&lt;your key&gt;/</code>.</li><li>In your podcast host, find the <strong>prefix</strong> or <strong>analytics prefix</strong> field (hosts name it differently) and paste the prefix there. It works alongside any other prefixes you already use.</li><li>Save. Back in PodSEO you can ask it to re-check your feed, to confirm the prefix is in place.</li></ol><h3 id="what-you-ll-see-5" tabindex="-1"><strong>What you&#39;ll see</strong> <a class="header-anchor" href="#what-you-ll-see-5" aria-label="Permalink to &quot;**What you&#39;ll see**&quot;">​</a></h3><ul><li><strong>Downloads</strong> for the period, with the change compared with the previous period</li><li><strong>Apps</strong>, <strong>countries</strong> and <strong>episodes</strong></li><li><strong>Not counted</strong>: the requests that were left out and why: cloud apps, servers, bots, preloads, and requests with no user agent. A toggle lets you include cloud apps in the count if you want to.</li></ul><p>Only your account can see your hopr.fm reports.</p><h3 id="how-downloads-are-counted" tabindex="-1"><strong>How downloads are counted</strong> <a class="header-anchor" href="#how-downloads-are-counted" aria-label="Permalink to &quot;**How downloads are counted**&quot;">​</a></h3><p>hopr.fm counts <strong>one download per day, per episode, per listener</strong>. To tell listeners apart without storing who they are, each listener is turned into a one-way code that changes every day. The method follows the IAB v2.3 measurement guidelines as far as a redirect prefix allows, but hopr.fm is <strong>not IAB certified</strong>.</p><h3 id="listener-privacy" tabindex="-1"><strong>Listener privacy</strong> <a class="header-anchor" href="#listener-privacy" aria-label="Permalink to &quot;**Listener privacy**&quot;">​</a></h3><p>hopr.fm only redirects the request to your audio file. It sets no cookies, deletes raw logs and per-listener records after 35 days, never sells data or builds ad profiles, and podcasters only ever see totals. The full listener privacy policy is at <a href="https://podseo.com/hoprfm/privacy/" target="_blank" rel="noreferrer">podseo.com/hoprfm/privacy</a>.</p><h3 id="how-fresh-5" tabindex="-1"><strong>How fresh</strong> <a class="header-anchor" href="#how-fresh-5" aria-label="Permalink to &quot;**How fresh**&quot;">​</a></h3><p>Downloads are processed throughout the day.</p><h3 id="disconnecting-5" tabindex="-1"><strong>Disconnecting</strong> <a class="header-anchor" href="#disconnecting-5" aria-label="Permalink to &quot;**Disconnecting**&quot;">​</a></h3><p>Remove the hopr.fm prefix from your host&#39;s settings. Downloads that no longer pass through the prefix aren&#39;t counted.</p><hr><h2 id="faq" tabindex="-1"><strong>FAQ</strong> <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;**FAQ**&quot;">​</a></h2><h3 id="do-i-have-to-share-my-passwords-with-podseo" tabindex="-1"><strong>Do I have to share my passwords with PodSEO?</strong> <a class="header-anchor" href="#do-i-have-to-share-my-passwords-with-podseo" aria-label="Permalink to &quot;**Do I have to share my passwords with PodSEO?**&quot;">​</a></h3><p>No. Spotify and Apple Podcasts are connected by inviting a PodSEO address to your show&#39;s team with read-only analytics access. YouTube and Spreaker use their own sign-in screens, where you approve access directly with Google or Spreaker. Buzzsprout uses an API token you copy from your Buzzsprout profile, not your password. PodSEO never sees your passwords, and you can disconnect at any time.</p><h3 id="which-podcast-hosts-can-i-connect" tabindex="-1"><strong>Which podcast hosts can I connect?</strong> <a class="header-anchor" href="#which-podcast-hosts-can-i-connect" aria-label="Permalink to &quot;**Which podcast hosts can I connect?**&quot;">​</a></h3><p>Spreaker and Buzzsprout today; more hosts are coming. If your host isn&#39;t supported yet, you can still get download numbers from OP3 (if your feed uses it) or by adding the free hopr.fm prefix, and connect Spotify, Apple Podcasts and YouTube regardless of where you host.</p><h3 id="what-s-the-difference-between-hopr-fm-and-op3" tabindex="-1"><strong>What&#39;s the difference between hopr.fm and OP3?</strong> <a class="header-anchor" href="#what-s-the-difference-between-hopr-fm-and-op3" aria-label="Permalink to &quot;**What&#39;s the difference between hopr.fm and OP3?**&quot;">​</a></h3><p>Both are download prefixes that count downloads on the way to the listener. OP3 is an independent, open service: its data is public to anyone and PodSEO shows about 60 days of it, with downloads per episode at 1, 7 and 30 days. hopr.fm is PodSEO&#39;s own prefix: its reports are private to your account, show apps, countries, episodes and a breakdown of what wasn&#39;t counted, and you choose whether to count cloud apps. You can use both at the same time.</p><h3 id="is-this-really-free" tabindex="-1"><strong>Is this really free?</strong> <a class="header-anchor" href="#is-this-really-free" aria-label="Permalink to &quot;**Is this really free?**&quot;">​</a></h3><p>Yes. Every connection is available on every plan, including Free. The one difference is YouTube: on the Free plan you see channel performance, one reported search term and your latest episode, while paid plans show every search term and all your recent episodes.</p><h3 id="why-don-t-my-numbers-match-exactly-between-sources" tabindex="-1"><strong>Why don&#39;t my numbers match exactly between sources?</strong> <a class="header-anchor" href="#why-don-t-my-numbers-match-exactly-between-sources" aria-label="Permalink to &quot;**Why don&#39;t my numbers match exactly between sources?**&quot;">​</a></h3><p>Each platform measures something different: Spotify and Apple count plays and listeners in their own apps, YouTube counts views, and hosts and prefixes count downloads across all apps. That&#39;s why PodSEO shows each source on its own tab instead of mixing them into one number.</p><h3 id="i-m-a-team-member-and-can-t-connect-why" tabindex="-1"><strong>I&#39;m a team member and can&#39;t connect. Why?</strong> <a class="header-anchor" href="#i-m-a-team-member-and-can-t-connect-why" aria-label="Permalink to &quot;**I&#39;m a team member and can&#39;t connect. Why?**&quot;">​</a></h3><p>In an organization, only Admins and Owners can connect or disconnect analytics sources. Ask one of them to set up the connection; once it&#39;s done, everyone on the team can see the numbers.</p><hr><h3 id="pro-tips" tabindex="-1"><strong>Pro Tips</strong> <a class="header-anchor" href="#pro-tips" aria-label="Permalink to &quot;**Pro Tips**&quot;">​</a></h3><ul><li>Start with the platforms where most of your audience listens, then add your host or a download prefix for a count across all apps.</li><li>Compare Spotify&#39;s <strong>impressions from Search</strong> with your <a href="/features/keyword-tracker.html">Keyword Tracker</a> rankings: rising rankings should show up as more search impressions.</li><li>Use the <strong>First 7 days</strong> and <strong>First 30 days</strong> columns (Apple and your host) to compare episodes fairly, regardless of how long ago they were published.</li><li>Check the Apple <strong>retention curve</strong> for episodes with a big drop early on: it shows where listeners leave, so you can compare it with how the episode opens.</li><li>If your host isn&#39;t supported yet, add the hopr.fm prefix: it takes a minute and gives you download numbers from that day on.</li></ul>',112)])])}const g=o(r,[["render",a]]);export{u as __pageData,g as default};
